138	/**
139	 * 주문 상태를 정의하는 Enum
140	 */
141	public enum OrderStatus {
142	    PENDING_PAYMENT, // 결제 대기
143	    PAYMENT_COMPLETED, // 결제 완료
144	    PREPARING, // 상품 준비 중
145	    IN_WAREHOUSE, // 창고 보관 중
146	    SHIPMENT_STARTED, // 배송 시작
147	    IN_TRANSIT, // 배송 중
148	    COMPLETED, // 배송 완료
149	    REFUND_REQUESTED, // 환불 대기
150	    REFUNDED; // 환불 완료
151	
152	    // 각 상태에서 전이 가능한 다음 상태들을 정의
153	    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED_TRANSITIONS = new HashMap<>();
154	
155	    static {
156	        // 상태 전이 규칙 초기화
157	        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
158	        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
159	        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
160	        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
161	        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
162	        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
163	        ALLOWED_TRANSITIONS.put(REFUND_REQUESTED, Set.of(REFUNDED));
164	        ALLOWED_TRANSITIONS.put(COMPLETED, Collections.emptySet());
165	        ALLOWED_TRANSITIONS.put(REFUNDED, Collections.emptySet());
166	    }
167	
168	    /**
169	     * 현재 상태에서 새 상태로 전이가 가능한지 확인합니다.
170	     *
171	     * @param newStatus 전이하려는 새 상태
172	     * @return 전이 가능 여부
173	     */
174	    public boolean canTransitionTo(OrderStatus newStatus) {
175	        Set<OrderStatus> allowedNextStates = ALLOWED_TRANSITIONS.get(this);
176	        return allowedNextStates != null && allowedNextStates.contains(newStatus);
177	    }
178	
179	    /**
180	     * 현재 상태에서 전이 가능한 모든 상태를 반환합니다.
181	     *
182	     * @return 전이 가능한 상태 집합
183	     */
184	    public Set<OrderStatus> getAllowedNextStates() {
185	        return Collections.unmodifiableSet(ALLOWED_TRANSITIONS.getOrDefault(this, Collections.emptySet()));
186	    }
