497	    @Transactional
498	    public void updatePaymentStatus(Payment payment, PaymentStatus newStatus) {
499	        Instant start = Instant.now();
500	        try {
501	            if (payment == null) {
502	                throw new PaymentNotFoundException("결제 정보가 없습니다.");
503	            }
504	
505	            if (!payment.getStatus().canTransitionTo(newStatus)) {
506	                throw new PaymentException(PaymentErrorCode.INVALID_PAYMENT_STATUS,
507	                        "현재 상태(" + payment.getStatus() + ")에서 " + newStatus + " 상태로 변경할 수 없습니다.");
508	            }
509	
510	            log.info("결제 상태 변경: 결제ID={}, 현재상태={}, 새상태={}",
511	                    payment.getId(), payment.getStatus(), newStatus);
512	
513	            payment.updateStatus(newStatus);
514	            paymentRepository.save(payment);
515	
516	            log.info("결제 상태 변경 완료: 결제ID={}, 상태={}", payment.getId(), newStatus);
517	
518	            // 처리 시간 로깅
519	            Instant end = Instant.now();
520	            Duration duration = Duration.between(start, end);
521	            log.debug("결제 상태 변경 처리 시간: {}ms", duration.toMillis());
522	        } catch (PaymentException e) {
523	            log.error("결제 상태 변경 실패: 결제ID={}, 에러코드={}, 메시지={}",
524	                    payment != null ? payment.getId() : "null",
525	                    e.getErrorCode().getCode(), e.getMessage());
526	            throw e; // 이미 PaymentException이면 그대로 전파
527	        } catch (Exception e) {
528	            log.error("결제 상태 변경 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
529	                    payment != null ? payment.getId() : "null", e.getMessage(), e);
530	            throw new PaymentException(PaymentErrorCode.PAYMENT_UPDATE_FAILED,
531	                    "결제 상태 변경 중 오류가 발생했습니다.", e);
532	        }
533	    }
