73:    73	    )
74:    74	    public String getAccessToken() {
75:    75	        Instant start = Instant.now();
76:    76	        String url = BASE_URL + TOKEN_URL;
77:    77	
78:    78	        log.info("PortOne API 토큰 발급 요청 시작");
79:    79	
80:    80	        // 요청 본문 생성
81:    81	        Map<String, String> requestBody = new HashMap<>();
82:    82	        requestBody.put("imp_key", impKey); // PortOne API 키
83:    83	        requestBody.put("imp_secret", impSecret); // PortOne API Secret
84:    84	
85:    85	        // HTTP 헤더 설정
86:    86	        HttpHeaders headers = new HttpHeaders();
87:    87	        headers.setContentType(MediaType.APPLICATION_JSON);
