97:    97	
98:    98	            if (response.getStatusCode() == HttpStatus.OK) {
99:    99	                Map<String, Object> responseBody = response.getBody();
100:   100	                Map<String, Object> responseContent = (Map<String, Object>) responseBody.get("response");
101:   101	
102:   102	                if (responseContent == null || responseContent.get("access_token") == null) {
103:   103	                    throw new PaymentApiException("토큰 발급 응답에서 access_token을 찾을 수 없습니다.");
104:   104	                }
105:   105	
106:   106	                String accessToken = (String) responseContent.get("access_token");
107:   107	                log.info("PortOne API 토큰 발급 성공: {}", accessToken.substring(0, Math.min(10, accessToken.length())) + "...");
108:   108	
109:   109	                // 처리 시간 로깅
110:   110	                Instant end = Instant.now();
111:   111	                Duration duration = Duration.between(start, end);
